pNext/><w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:before=\"240\" w:after=\"240\"/><w:jc w:val=\"center\"/></w:pPr><w:bookmarkStart w:id=\"28\" w:name=\"_heading=h.2et92p0\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"28\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr><w:lastRenderedPageBreak/><w:br/><w:t>GENERAL OBLIGATIONS</w:t></w:r></w:p><w:p w14:paraId=\"41D8CD59\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"29\" w:name=\"_heading=h.tyjcwt\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"29\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Research Project</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">.  </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:u w:val=\"single\"/></w:rPr><w:t>Exhibit A</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> hereto (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Project Description</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>”) sets forth the research and other activities to be conducted by University (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Research Project</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>”).  The Project Description identifies: (a) the general description of the Research Project; (b) the scope of work to be undertaken by University; (c) the schedule under which such scope of work is to be completed; (d) the principal steps for carrying out the Research Project (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Research Steps</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>”); (e) the deliverables to be provided by University to Colgate (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Deliverables</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>”); (f) milestones; (g) the Fees (as defined below); and (h) the approved expenses.</w:t></w:r></w:p><w:p w14:paraId=\"354A95B1\" w14:textId=\"098C81F9\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Performance of Obligations</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:color w:val=\"000000\"/></w:rPr><w:t>.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  University shall, and shall cause its Representatives and permitted subcontractors to, perform all of the tasks and obligations set forth in the Project Description (including the performance of the Research Steps and delivery of the Deliverables), together with any tasks and obligations not specifically described in the Project Description but which are inherent in or a necessary part of the tasks and obligations described in the Project Description, or are reasonably required for proper performance of such tasks and obligations.  University shall be responsible for acquiring all necessary equipment, materials and tools necessary to conduct the Research Project other than the Materials, if any.  University shall complete each milestone set forth in the Project Description within the period specified in the Project Description for such milestone.  All Deliverables delivered by </w:t></w:r><w:proofErr w:type=\"gramStart\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>University</w:t></w:r><w:proofErr w:type=\"gramEnd\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> are subject to Colgate’s acceptance, and University shall re-perform and re-deliver any Deliverable that is not accepted by Colgate.  No payment under this Agreement by Colgate shall be evidence of the performance of </w:t></w:r><w:proofErr w:type=\"gramStart\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>University</w:t></w:r><w:proofErr w:type=\"gramEnd\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> or the acceptance of any Deliverable.</w:t></w:r></w:p><w:p w14:paraId=\"095D7049\" w14:textId=\"03E0A986\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"30\" w:name=\"_heading=h.3dy6vkm\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"30\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Removal of Personnel</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">.  University shall maintain staffing levels and continuity of personnel consistent with its obligation to perform the Research Project.  University shall not remove or redeploy </w:t></w:r><w:r w:rsidR=\"00180E45\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>the Research Project Manager</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> without the prior written permission of Colgate.  If any Representatives performing the Research Project are unacceptable to Colgate for any reason, Colgate reserves the right to notify University in which case University shall </w:t></w:r><w:ins w:id=\"31\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T10:22:00Z\" w16du:dateUtc=\"2026-04-06T15:22:00Z\"><w:r w:rsidR=\"00E004FE\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>promptly</w:t></w:r></w:ins><w:del w:id=\"32\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T10:22:00Z\" w16du:dateUtc=\"2026-04-06T15:22:00Z\"><w:r w:rsidRPr=\"00DA6010\" w:rsidDel=\"00E004FE\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:delText>immediately</w:delText></w:r></w:del><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> remove such Representatives from performing the Research Project hereunder and, if requested by Colgate, provide a qualified replacement.  If University provides replacement Representatives for any reason, University shall not charge Colgate for the number of hours required to train the replacement until such Representatives are familiar with the particular Research Project, so that such replacement Representatives are capable of performing the Research Project in accordance with this Agreement.</w:t></w:r></w:p><w:p w14:paraId=\"60A950D9\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"33\" w:name=\"_heading=h.1t3h5sf\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"33\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Materials</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.  Colgate will provide the materials identified in the Project Description, if any (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Materials</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>”), to University for the performance of the Research Project.  University shall not use the Materials other than for the performance of the Research Project and expressly agrees not to analyze, attempt to identify, modify or otherwise reverse engineer the Materials to determine their composition.  Upon the completion of the Research Project, University shall return all unused Materials to Colgate, unless otherwise instructed by Colgate in writing.  The Materials are Confidential Information of Colgate.</w:t></w:r></w:p><w:p w14:paraId=\"5A8F74BD\" w14:textId=\"20704AF8\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Subcontractors</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:bCs/><w:color w:val=\"000000\"/></w:rPr><w:t>.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  University may not subcontract or engage any Third Party to perform any of its tasks or obligations hereunder, or consult with any Third Party regarding such </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:lastRenderedPageBreak/><w:t xml:space=\"preserve\">tasks and obligations, unless: (a) Colgate provides written approval in advance; and (b) such Third Party enters into an agreement having commercial, Intellectual Property and confidentiality terms that are approved in writing by Colgate.  No such subcontracting shall relieve University of its obligations under this Agreement and University shall be responsible for the actions and inactions of all of its permitted subcontractors as if such actions and inactions were committed by </w:t></w:r><w:proofErr w:type=\"gramStart\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>University</w:t></w:r><w:proofErr w:type=\"gramEnd\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:sz w:val=\"26\"/><w:szCs w:val=\"26\"/><w:vertAlign w:val=\"superscript\"/></w:rPr><w:t xml:space=\"preserve\"> </w:t></w:r></w:p><w:p w14:paraId=\"10D16A1E\" w14:textId=\"77777777\" w:rsidR=\"008149A5\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Exclusivity</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>. During the Term, University shall not (and shall cause its Affiliates not to), itself or in collaboration with or pursuant to a contract or agreement with or for the benefit of any Third Party, engage in, undertake or otherwise pursue, a research, development or commercialization project which may be adverse to or conflict with the Research Project or is identical or similar to the Research Project, including similar work for any of Colgate’s direct competitors in competing categories, without the prior written consent of Colgate.</w:t></w:r></w:p><w:p w14:paraId=\"4C7E63AE\" w14:textId=\"3EFAFB1C\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\" w:rsidP=\"008149A5\"><w:pPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"720\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"27C2EF11\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:keepNext/><w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:before=\"240\" w:after=\"240\"/><w:jc w:val=\"center\"/></w:pPr><w:bookmarkStart w:id=\"34\" w:name=\"_heading=h.4d34og8\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"34\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr><w:br/><w:t>MANAGEMENT OF THE RESEARCH PROJECT</w:t></w:r></w:p><w:p w14:paraId=\"7C5A2561\" w14:textId=\"74F8F60D\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"35\" w:name=\"_heading=h.2s8eyo1\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"35\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Research Project Managers</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:bCs/><w:color w:val=\"000000\"/></w:rPr><w:t>.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  Each Party hereby appoints the Research Project manager for such Party set forth in </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:u w:val=\"single\"/></w:rPr><w:t>Exhibit B</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> (each, a “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Research Project Manager</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">”) to act as the primary contact for such Party in connection with matters related to the Research Project.  Either Party may replace its Research Project Manager at any time by providing written notice to the other Party.  University’s Research Project Manager shall keep Colgate’s Research Project Manager apprised of the status of the Research Project and of the various Research Steps at all times.  The Research Project Managers will meet at least </w:t></w:r><w:r w:rsidR=\"002A52A7\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>quarterly</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>, or more frequently as agreed by the Research Project Managers, and such meetings may be held by videoconference or telephone conference.</w:t></w:r></w:p><w:p w14:paraId=\"29590203\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"008149A5\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/></w:pPr><w:bookmarkStart w:id=\"36\" w:name=\"_heading=h.17dp8vu\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"36\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Compliance with Policies While On-Site</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.  While at the offices or facilities of Colgate and its Affiliates, University and its Representatives shall comply with all applicable policies and procedures of Colgate (including security policies and procedures) as provided to University and its Representatives in writing or explained in a formal course on security.</w:t></w:r></w:p><w:p w14:paraId=\"3030F225\" w14:textId=\"77777777\" w:rsidR=\"008149A5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"008149A5\" w:rsidP=\"008149A5\"><w:pPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"720\"/><w:jc w:val=\"both\"/></w:pPr></w:p><w:p w14:paraId=\"56AEE5A9\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:keepNext/><w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:before=\"240\" w:after=\"240\"/><w:jc w:val=\"center\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr><w:br/><w:t>FEES</w:t></w:r></w:p><w:p w14:paraId=\"0EAD638F\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/></w:pPr><w:bookmarkStart w:id=\"37\" w:name=\"_heading=h.3rdcrjn\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"37\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Fees</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.  In consideration of University’s performance of the Research Project, Colgate shall pay to University the fees as set forth in the Project Description (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Fees</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>”).  University agrees to establish an account with Colgate’s electronic invoicing provider for the submission and payment of all invoices.  After the Fees have become due, as set forth in the Project Description, University shall submit an invoice electronically.  All undisputed Fees shall be paya</w:t></w:r><w:r w:rsidR=\"00FE6A15\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>ble by Colgate within ninety (90</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">) days after Colgate’s receipt of an acceptable invoice for such Fees from University; </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:u w:val=\"single\"/></w:rPr><w:t>provided</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> that University may only issue such an invoice after such Fees have become due pursuant to the Project Description.  All payments will be made by Colgate </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:lastRenderedPageBreak/><w:t>to University via a wire transfer.  Any sales, use, excise, value-added or other taxes or duties and penalties and interest relating thereto shall be the sole responsibility of University.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:sz w:val=\"26\"/><w:szCs w:val=\"26\"/><w:vertAlign w:val=\"superscript\"/></w:rPr><w:t xml:space=\"preserve\"> </w:t></w:r></w:p><w:p w14:paraId=\"2CD10C4A\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"0010020D\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>No Other Costs</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.  Except as otherwise set forth in the Project Description, all direct and indirect costs and expenses (including any travel costs, legal and other advisory fees and other Third-Party costs) in connection with this Agreement incurred by University or its Representatives shall be borne solely by University, and Colgate shall have no obligation to reimburse University for any such costs or expenses.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:sz w:val=\"26\"/><w:szCs w:val=\"26\"/><w:vertAlign w:val=\"superscript\"/></w:rPr><w:t xml:space=\"preserve\"> </w:t></w:r></w:p><w:p w14:paraId=\"4AC38CD2\" w14:textId=\"77777777\" w:rsidR=\"0010020D\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"0010020D\" w:rsidP=\"0010020D\"><w:pPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"720\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"6AD13438\" w14:textId=\"49192491\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:keepNext/><w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:before=\"240\" w:after=\"240\"/><w:jc w:val=\"center\"/></w:pPr><w:bookmarkStart w:id=\"38\" w:name=\"_heading=h.26in1rg\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"38\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr><w:br/><w:t>INTELLECTUAL PROPERTY</w:t></w:r></w:p><w:p w14:paraId=