 Party</w:delText></w:r></w:del><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.</w:t></w:r></w:p><w:p w14:paraId=\"07364CE6\" w14:textId=\"1E66B6D1\" w:rsidR=\"002266B5\" w:rsidRPr=\"009533E8\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Survival</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">.  </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">The mutual obligations of confidentiality and non-use under this Article 10 shall survive the expiration and earlier termination of this Agreement for a period of </w:t></w:r><w:r w:rsidR=\"00221F8B\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">three </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>(</w:t></w:r><w:r w:rsidR=\"00221F8B\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>3</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>) years after its expiration or earlier termination.</w:t></w:r></w:p><w:p w14:paraId=\"151C730F\" w14:textId=\"77777777\" w:rsidR=\"009533E8\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009533E8\" w:rsidP=\"009533E8\"><w:pPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"720\"/><w:jc w:val=\"both\"/></w:pPr></w:p