\"00221F8B\" w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:bCs/><w:color w:val=\"000000\"/></w:rPr><w:t>twelve (12) months</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Term</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>”).</w:t></w:r></w:p><w:p w14:paraId=\"0146DD1F\" w14:textId=\"63F023C6\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"186\" w:name=\"_heading=h.32hioqz\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"186\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Termination</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:bCs/><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">. </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> This Agreement may be terminated as follows:</w:t></w:r></w:p><w:p w14:paraId=\"169D9441\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"2\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"187\" w:name=\"_heading=h.1hmsyys\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"187\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Material Breach</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.  This Agreement (in its entirety) may be terminated by either Party (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Nonbreaching Party</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>”) upon written notice thereof to the other Party (the “</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Breaching Party</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">”) in the event of a material breach of this Agreement by the Breaching Party which is not cured within sixty (60) days after the receipt by the Breaching Party of written notice from the Nonbreaching Party, specifying in reasonable detail the nature of such breach.  If such breach is not cured within such cure period, this Agreement shall terminate as set forth in the Nonbreaching Party’s notice of breach and in accordance with the terms of this Article; </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:u w:val=\"single\"/></w:rPr><w:t>provided</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>,</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:u w:val=\"single\"/></w:rPr><w:t>however</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">, that this Agreement shall not be terminated prior to the end of such cure period.  </w:t></w:r></w:p><w:p w14:paraId=\"364D389D\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"2\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"188\" w:name=\"_heading=h.41mghml\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"188\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Insolvency</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:color w:val=\"000000\"/></w:rPr><w:t>.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  This Agreement may be terminated by either Party upon sixty (60) days’ prior written notice to the other Party at any time during this Agreement if the other Party: (a) files in any court pursuant to any statute a petition in bankruptcy or insolvency or for reorganization or for an arrangement or for the appointment of a receiver or trustee of the other Party, or of its assets; (b) proposes a written agreement of composition for extension of its debts; (c) is served with an involuntary petition against it, filed in any insolvency proceeding, and such petition shall not be dismissed within sixty (60) days after filing thereof; or (d) makes an assignment for the benefit of its creditors.  The Party affected shall immediately notify the other Party in writing of the occurrence of any of the foregoing events.</w:t></w:r></w:p><w:p w14:paraId=\"4B81AA73\" w14:textId=\"541B3BBB\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"2\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"189\" w:name=\"_heading=h.2grqrue\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"189\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>For Convenience</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">.  This Agreement may be terminated by Colgate for any or no reason by providing University with written notice at least thirty (30) days prior to the desired effective date of termination.  If Colgate elects to terminate this Agreement pursuant to this Section 11.2.3, University shall be entitled to receive Fees for </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:lastRenderedPageBreak/><w:t>the Research Steps performed until the termination date of this Agreement but Colgate shall have no other liability to University as a result of such termination of this Agreement.</w:t></w:r></w:p><w:p w14:paraId=\"4874E3FB\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Cumulative Remedies</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:bCs/><w:color w:val=\"000000\"/></w:rPr><w:t>.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  Except as expressly stated otherwise herein, remedies under this Agreement are cumulative, and nothing in this Agreement shall prevent any Party, in the case of a material breach (after expiration of applicable cure period and notice periods), from terminating this Agreement and seeking to enforce its rights under this Agreement.</w:t></w:r></w:p><w:p w14:paraId=\"475AE4BB\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"190\" w:name=\"_heading=h.vx1227\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"190\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Consequences of Termination</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:bCs/><w:color w:val=\"000000\"/></w:rPr><w:t>.</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  Upon expiration or termination of this Agreement:</w:t></w:r></w:p><w:p w14:paraId=\"0505BDE4\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"3\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">each Party shall either (at the sole discretion of such Party) deliver to the other Party or destroy all Confidential Information and original technical data and technology supplied by the other Party pursuant to this Agreement to such Party; </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:u w:val=\"single\"/></w:rPr><w:t>provided</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">, </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/><w:u w:val=\"single\"/></w:rPr><w:t>however</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>, that each Party may retain an archival copy or other appropriate record (including electronic backup copies created in the ordinary course) of any such Confidential Information.  Such copies and records may be used exclusively for internal recordkeeping and administrative purposes, to assure compliance with any applicable Governmental Authority requirements and for dispute resolution purposes;</w:t></w:r></w:p><w:p w14:paraId=\"48529324\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"3\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/></w:pPr><w:bookmarkStart w:id=\"191\" w:name=\"_heading=h.3fwokq0\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"191\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>University shall, in accordance with such Colgate’s instructions, deliver to Colgate: (i) all materials, products or equipment of Colgate previously provided to University in connection with the Research Project, including the Materials pursuant to this Agreement; and (ii) all Deliverables (including Deliverables in progress) developed under this Agreement; and</w:t></w:r></w:p><w:p w14:paraId=\"22E3B894\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"3\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>If either Party terminates prior to the expiration of the Term (other than by Colgate for University’s breach), Colgate shall, within sixty (60) days after the effective date of termination, pay University the Fees associated with Research Steps completed by University under this Agreement prior to either Party providing the other with notice of termination.  All Fees advanced by Colgate to University and not earned by University under this Agreement shall be reimbursed by University to Colgate within sixty (60) days after the effective date of termination.</w:t></w:r></w:p><w:p w14:paraId=\"152CB9D8\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"192\" w:name=\"_heading=h.1v1yuxt\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"192\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Survival</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.  All provisions under this Agreement which by their terms survive, or by their nature should survive, expiration or any earlier termination of this Agreement shall survive any such expiration or termination, including Article 1, Article 5, Article 6, Section 7.1, Section 8.7, Article 9, Article 10, Section 11.4, this Section 11.5 and Article 12.</w:t></w:r></w:p><w:p w14:paraId=\"6A36522D\" w14:textId=\"77777777\" w:rsidR=\"002D58F6\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002D58F6\" w:rsidP=\"002D58F6\"><w:pPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"720\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"6FE25028\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:keepNext/><w:numPr><w:ilvl w:val=\"0\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:before=\"240\" w:after=\"240\"/><w:jc w:val=\"center\"/></w:pPr><w:bookmarkStart w:id=\"193\" w:name=\"_heading=h.4f1mdlm\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"193\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr><w:br/><w:t>MISCELLANEOUS</w:t></w:r></w:p><w:p w14:paraId=\"582A13AD\" w14:textId=\"73EA7CB7\" w:rsidR=\"002266B5\" w:rsidRPr=\"005A5DB1\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"1440\"/><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:ins w:id=\"194\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:05:00Z\" w16du:dateUtc=\"2026-04-06T22:05:00Z\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"195\" w:name=\"_heading=h.2u6wntf\" w:colFirst=\"0\