:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:tabs><w:tab w:val=\"left\" w:pos=\"2160\"/></w:tabs><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:bookmarkStart w:id=\"231\" w:name=\"_heading=h.3tbugp1\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkStart w:id=\"232\" w:name=\"_heading=h.28h4qwu\" w:colFirst=\"0\" w:colLast=\"0\"/><w:bookmarkEnd w:id=\"231\"/><w:bookmarkEnd w:id=\"232\"/><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:i/><w:color w:val=\"000000\"/></w:rPr><w:t>Dispute Resolution</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.  Subject to Section 12.</w:t></w:r><w:ins w:id=\"233\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:44:00Z\" w16du:dateUtc=\"2026-04-06T22:44:00Z\"><w:r w:rsidR=\"006A49BE\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>5</w:t></w:r></w:ins><w:del w:id=\"234\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:44:00Z\" w16du:dateUtc=\"2026-04-06T22:44:00Z\"><w:r w:rsidR=\"00180E45\" w:rsidRPr=\"00DA6010\" w:rsidDel=\"006A49BE\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:delText>4</w:delText></w:r></w:del><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">.4 below, any dispute between the Parties arising out of, related to or in connection with this Agreement shall be </w:t></w:r><w:ins w:id=\"235\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:43:00Z\" w16du:dateUtc=\"2026-04-06T22:43:00Z\"><w:r w:rsidR=\"00A05503\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">addressed </w:t></w:r><w:r w:rsidR=\"000E6B96\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">through </w:t></w:r></w:ins><w:del w:id=\"236\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:43:00Z\" w16du:dateUtc=\"2026-04-06T22:43:00Z\"><w:r w:rsidRPr=\"00DA6010\" w:rsidDel=\"006A49BE\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:delText xml:space=\"preserve\">resolved exclusively by invoking the </w:delText></w:r></w:del><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">following </w:t></w:r><w:ins w:id=\"237\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:44:00Z\" w16du:dateUtc=\"2026-04-06T22:44:00Z\"><w:r w:rsidR=\"00B854A7\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>NON-BINDING</w:t></w:r><w:r w:rsidR=\"006A49BE\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> </w:t></w:r></w:ins><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>dispute resolution procedures</w:t></w:r><w:ins w:id=\"238\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:44:00Z\" w16du:dateUtc=\"2026-04-06T22:44:00Z\"><w:r w:rsidR=\"006A49BE\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>, with each Party committing to act in good faith throughout the process</w:t></w:r></w:ins><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>:</w:t></w:r></w:p><w:p w14:paraId=\"3E017D1A\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"2\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  The Parties agree to make a diligent, good faith effort to resolve all disputes amicably if at all possible. To this end, authorized representatives of each Party shall meet within fifteen (15) days after receipt of written notice by either Party at a mutually agreeable time and place to discuss possible resolution of the dispute.</w:t></w:r></w:p><w:p w14:paraId=\"5A2931E0\" w14:textId=\"77D15AA6\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"2\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  In the event that the Parties</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\"> </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>are unable to resolve the dispute within fifteen (15) days after their meeting, then either Party may invoke non-binding mediation under the International Institute for Conflict Prevention &amp; Resolution (“CPR”) Mediation Procedure then in effect. Unless otherwise agreed in writing by the Parties, the Parties will select a single mediator from the CPR Panels of Distinguished Neutrals. The mediation proceeding shall be conducted in New York, New York, or such other location as may be agreed in writing by the Parties. The Parties shall (a) share equally the fees and expenses of the mediator; and (b) bear their own attorneys’ fees and associated costs and expenses. At the request of either Party, the mediator shall enter an appropriate protective order to maintain the confidentiality of information produced or exchanged in the course of the mediation proceedings. The Parties shall use their best efforts to complete the mediation procedure provided for in this Section 12.</w:t></w:r><w:r w:rsidR=\"00180E45\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">4 </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>within no more than sixty (60) days.</w:t></w:r></w:p><w:p w14:paraId=\"796B39A2\" w14:textId=\"2460B1EA\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"2\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  After (i) completion of the process described in Section 12.</w:t></w:r><w:r w:rsidR=\"00180E45\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>4</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.1 and Section 12.</w:t></w:r><w:r w:rsidR=\"00180E45\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>4</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">.2 above or (ii) the non-cooperation of either Party in the completion of the stated procedure, then either Party (in the case of clause (i)) or the cooperating Party (in the case of clause (ii)) may initiate an action in court against the other, but such action may only be brought in a court </w:t></w:r><w:r w:rsidR=\"00180E45\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">of competent </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>jurisdiction. All applicable statutes of limitation and defenses based upon the passage of time shall be tolled while the process described in Section 12.</w:t></w:r><w:r w:rsidR=\"00180E45\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>4</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.1 and Section 12.</w:t></w:r><w:r w:rsidR=\"00180E45\" w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>4</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t>.2 above is pending. The Parties shall take such action, if any, required to effectuate such tolling.</w:t></w:r></w:p><w:p w14:paraId=\"218F0533\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:numPr><w:ilvl w:val=\"2\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"both\"/><w:rPr><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:t xml:space=\"preserve\">  Nothing in this Section 12.5 shall be construed to prevent either Party from seeking injunctive relief against the other Party from any judicial or administrative authority of competent jurisdiction to enjoin such other Party from </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:color w:val=\"000000\"/></w:rPr><w:lastRenderedPageBreak/><w:t>breaching any provision of this Agreement pending the resolution of a dispute as hereinbefore provided.</w:t></w:r></w:p><w:p w14:paraId=\"3F4DA207\" w14:textId=\"096CC70A\" w:rsidR=\"00B854A7\" w:rsidRPr=\"002D002D\" w:rsidRDefault=\"002D002D\"><w:pPr><w:numPr><w:ilvl w:val=\"1\"/><w:numId w:val=\"2\"/></w:numPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:ind w:left=\"0\"/><w:jc w:val=\"both\"/><w:rPr><w:ins w:id=\"239\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:44:00Z\" w16du:dateUtc=\"2026-04-06T22:44:00Z\"/><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:bCs/><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:ins w:id=\"240\" w:author=\"Mixell, Daniel S.\" w:date=\"2026-04-06T17:45:00Z\" w16du:dateUtc=\"2026-04-06T22:45:00Z\">