p r:embed=\"rId22\"/><a:srcRect/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x=\"0\" y=\"0\"/><a:ext cx=\"2878455\" cy=\"421640\"/></a:xfrm><a:prstGeom prst=\"rect\"><a:avLst/></a:prstGeom><a:ln/></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p><w:p w14:paraId=\"75FB46A9\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:pBdr><w:top w:val=\"nil\"/><w:left w:val=\"nil\"/><w:bottom w:val=\"nil\"/><w:right w:val=\"nil\"/><w:between w:val=\"nil\"/></w:pBdr><w:spacing w:after=\"240\"/><w:jc w:val=\"center\"/><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:rFonts w:ascii=\"Times\" w:eastAsia=\"Times\" w:hAnsi=\"Times\" w:cs=\"Times\"/><w:b/><w:color w:val=\"000000\"/></w:rPr><w:t>EXHIBIT C</w:t></w:r></w:p><w:p w14:paraId=\"43D2C99D\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:spacing w:before=\"18\" w:line=\"361\" w:lineRule=\"auto\"/><w:ind w:left=\"2230\" w:right=\"-20\"/><w:rPr><w:sz w:val=\"32\"/><w:szCs w:val=\"32\"/></w:rPr></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:b/><w:color w:val=\"4F81BD\"/><w:sz w:val=\"32\"/><w:szCs w:val=\"32\"/></w:rPr><w:t>GLOBAL ANTI-BRIBERY POLICY</w:t></w:r></w:p><w:p w14:paraId=\"4B17E511\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:line=\"200\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"20\"/><w:szCs w:val=\"20\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"6EBB907E\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:spacing w:before=\"29\"/><w:ind w:left=\"3262\" w:right=\"3242\"/><w:jc w:val=\"center\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:u w:val=\"single\"/></w:rPr><w:t>Our Anti-Bribery Commitment</w:t></w:r></w:p><w:p w14:paraId=\"2CA33161\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"16\" w:line=\"260\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"22\"/><w:szCs w:val=\"22\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"0BAA169B\" w14:textId=\"43B84FB1\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:ind w:left=\"120\" w:right=\"57\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>Colgate’s commitment to dealing legally and ethically applies worldwide.  We comply with all applicable anti-bribery laws, including but not limited to the U.S. Foreign Corrupt Practices Act (“FCPA”), everywhere we do business, and we expect the same of th</w:t></w:r><w:r w:rsidR=\"00C8524E\" w:rsidRPr=\"00DA6010\"><w:t xml:space=\"preserve\">e third parties with whom we </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:t>work.  While the FCPA prohibits, among other things, bribery of foreign government officials and entities, other anti-bribery laws, like the UK Bribery Act, prohibit commercial bribery between private individuals and entities.</w:t></w:r></w:p><w:p w14:paraId=\"715A6DC0\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:line=\"200\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"22\"/><w:szCs w:val=\"22\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"3531470D\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:spacing w:before=\"29\"/><w:ind w:left=\"120\" w:right=\"54\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>Colgate people and any third parties acting on our behalf or in connection with our business are prohibited from giving or offering anything of value directly or indirectly to any government official or entity, or to any private individual or entity, in order to improperly obtain or retain any business advantage or to improperly affect any act or decision.</w:t></w:r></w:p><w:p w14:paraId=\"3E7F9191\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"3\" w:line=\"190\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"22\"/><w:szCs w:val=\"22\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"0956C5B0\" w14:textId=\"4EA2701E\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:spacing w:before=\"29\"/><w:ind w:left=\"120\" w:right=\"58\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>This prohibition includes any facilitating, expediting or “grease” payments made to government officials, either directly or indirectly, in order to expedite any official service or function (for example, small payments made to an official to move Colgate’s application to the front of the line or to shorten the time frame in which services or other actions are provided).  Any official fees supported by government-issued receipts do not qualify as improper payments.</w:t></w:r></w:p><w:p w14:paraId=\"60EAA131\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"16\" w:line=\"260\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"22\"/><w:szCs w:val=\"22\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"2436ADBE\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:spacing w:line=\"271\" w:lineRule=\"auto\"/><w:ind w:left=\"2786\" w:right=\"-20\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:u w:val=\"single\"/></w:rPr><w:t>Maintaining Accurate Books and Records</w:t></w:r></w:p><w:p w14:paraId=\"60B41CCD\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"12\"/><w:rPr><w:sz w:val=\"22\"/><w:szCs w:val=\"22\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"78C1C8F3\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:spacing w:before=\"29\"/><w:ind w:left=\"120\" w:right=\"57\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>No payment by or on behalf of the Company shall be approved or made if any part of the payment is to be used for an unlawful or improper purpose, or for any purpose other than that described by valid documents supporting the payment.  No false or misleading entries should be made in any books or financial records of the Company for any reason.</w:t></w:r></w:p><w:p w14:paraId=\"3D47025F\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"16\" w:line=\"260\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"22\"/><w:szCs w:val=\"22\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"6832C629\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:ind w:left=\"120\" w:right=\"59\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>Any expenses that an employee or third party incurs on Colgate’s behalf or in connection with our business shall not be reimbursable unless they are lawful and supported by detailed documentation including, for example, valid invoices or receipts.</w:t></w:r></w:p><w:p w14:paraId=\"7EE8EFF4\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"16\" w:line=\"260\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"22\"/><w:szCs w:val=\"22\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"439501DB\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:ind w:left=\"2566\" w:right=\"-20\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:u w:val=\"single\"/></w:rPr><w:t>Expenditures Related to Government Officials</w:t></w:r></w:p><w:p w14:paraId=\"467513DD\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"16\" w:line=\"260\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"22\"/><w:szCs w:val=\"22\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"1487CEF1\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\" w:rsidP=\"00C8524E\"><w:pPr><w:ind w:left=\"120\" w:right=\"58\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>No funds may be provided to or spent on behalf of a government official or entity, directly or indirectly, without advance written approval from Colgate’s Global Legal Organization.  This includes any payments, gifts, donations, entertainment, travel, meals, or other items of value. (For additional information, please review the Global Policy on Expenditures Related to Government Officials &amp; Governments.)  Advance approval is not required for official fees supported by government-issued receipts (e.g., perm</w:t></w:r><w:r w:rsidR=\"00C8524E\" w:rsidRPr=\"00DA6010\"><w:t>it or license fees)</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:t>Please note that the term “government official” is widely defined and may include individuals who are employed by any public or state-affiliated institution or organization or who act in an official capacity in any way, whether full-time, part-time or unpaid.  Government officials can be found in every branch and level of government and public life and may include anyone from low-level customs employees, to employees of state-owned media outlets, to high-ranking lawmakers, as well as researchers, professors, teachers, dentists, veterinarians, or other professionals and Key Thought Leaders.  If you are in doubt as to whether an individual could be considered a government official, you should contact the Global Legal Organization.</w:t></w:r></w:p><w:p w14:paraId=\"391ABC3B\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"16\" w:line=\"260\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"26\"/><w:szCs w:val=\"26\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"51B4049D\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:jc w:val=\"center\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:u w:val=\"single\"/></w:rPr><w:t>Commercial Bribery</w:t></w:r></w:p><w:p w14:paraId=\"0221EB6F\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"16\" w:line=\"260\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"26\"/><w:szCs w:val=\"26\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"6A51A01E\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:ind w:right=\"54\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>In addition to prohibiting bribery of government officials, Colgate also prohibits its employees and third parties from engaging in bribery of private parties.  You should not seek to improperly influence the judgment or conduct of any party with whom you might be conducting Company business by offering or providing any payments, gifts or other benefits, or by any other unlawful inducement.</w:t></w:r></w:p><w:p w14:paraId=\"587891D7\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\"><w:pPr><w:spacing w:line=\"271\" w:lineRule=\"auto\"/><w:jc w:val=\"center\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:u w:val=\"single\"/></w:rPr><w:t>Our Expectations</w:t></w:r></w:p><w:p w14:paraId=\"247FC803\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:before=\"12\"/></w:pPr></w:p><w:p w14:paraId=\"5528EBF0\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\" w:rsidP=\"009B216F\"><w:pPr><w:spacing w:before=\"29\"/><w:ind w:right=\"85\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>Colgate’s reputation depends on the conduct of our employees as well as the conduct of those with whom we do business.  It is our goal to ensure that Colgate People and the third parties with whom we work reflect the same high ethical standards and demonstrate a commitment to compliance with all applicable laws.  We further expect our third parties to ensure that their employees and subcontractors understand and comply with this Anti-Bribery Policy.</w:t></w:r></w:p><w:p w14:paraId=\"34AFFB46\" w14:textId=\"77777777\" w:rsidR=\"009B216F\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009B216F\"><w:pPr><w:spacing w:before=\"29\"/><w:ind w:right=\"85\"/></w:pPr></w:p><w:p w14:paraId=\"1DF02FA7\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"009015F9\" w:rsidP=\"009B216F\"><w:pPr><w:ind w:right=\"180\"/><w:jc w:val=\"both\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>Failure to comply with this Anti-Bribery Policy or any applicable anti-bribery laws, including but not limited to the FCPA, may result in civil or criminal penalties, as well as termination of the employment or business relationship.</w:t></w:r></w:p><w:p w14:paraId=\"2260EEDD\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRPr=\"00DA6010\" w:rsidRDefault=\"002266B5\"><w:pPr><w:spacing w:line=\"190\" w:lineRule=\"auto\"/><w:rPr><w:sz w:val=\"19\"/><w:szCs w:val=\"19\"/></w:rPr></w:pPr></w:p><w:p w14:paraId=\"7BB85BEA\" w14:textId=\"77777777\" w:rsidR=\"002266B5\" w:rsidRDefault=\"00C8524E\"><w:pPr><w:spacing w:before=\"29\"/><w:ind w:left=\"389\" w:right=\"92\"/><w:jc w:val=\"center\"/></w:pPr><w:r w:rsidRPr=\"00DA6010\"><w:t>A</w:t></w:r><w:r w:rsidR=\"009015F9\" w:rsidRPr=\"00DA6010\"><w:t>ny questions regarding this policy may be directed to our Global Complian</w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:t xml:space=\"preserve\">ce Legal Specialist: </w:t></w:r><w:r w:rsidRPr=\"00DA6010\"><w:rPr><w:u w:val=\"single\"/></w:rPr><w:t>Legal_Compliance</w:t></w:r><w:r w:rsidR=\"009015F9\" w:rsidRPr=\"00DA6010\"><w:rPr><w:u w:val=\"single\"/></w:rPr><w:t>@colpal.com</w:t></w:r></w:p><w:p w14:paraId=\"62DEAB8C\" w14:textId=\"34081554\" w:rsidR=\"002266B5\" w:rsidRDefault=\"002266B5\" w:rsidP=\"009B216F\"><w:pPr><w:rPr><w:rFonts w:ascii=\"Calibri\" w:eastAsia=\"Calibri\" w:hAnsi=\"Calibri\" w:cs=\"Calibri\"/></w:rPr></w:pPr></w:p><w:sectPr w:rsidR=\"002266B5\" w:rsidSect=\"009B216F\"><w:footerReference w:type=\"default\" r:id=\"rId23\"/><w:headerReference w:type=\"first\" r:id=\"rId24\"/><w:footerReference w:type=\"first\" r:id=\"rId25\"/><w:pgSz w:w=\"12240\" w:h=\"15840\"/><w:pgMar w:top=\"1440\" w:right=\"1440\" w:bottom=\"1440\" w:left=\"1440\" w:header=\"1008\" w:footer=\"1008\" w:gutter=\"0\"/><w:cols w:space=\"720\"/><w:titlePg/><w:docGrid w:linePitch=\"326\"/></w:sectPr></w:body></w:document></pkg:xmlData></pkg:part><pkg:part pkg:name=\"/word/_rels/document.xml.rels\" pkg:contentType=\"application/vnd.openxmlformats-package.relationships+xml\"><pkg:xmlData><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId8\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/endnotes\" Target=\"endnotes.xml\"/><Relationship Id=\"rId13\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer\" Target=\"footer1.xml\"/><Relationship Id=\"rId18\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/header\" Target=\"header4.xml\"/><Relationship Id=\"rId26\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/fontTable\" Target=\"fontTable.xml\"/><Relationship Id=\"rId3\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/numbering\" Target=\"numbering.xml\"/><Relationship Id=\"rId21\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink\" Target=\"mailto:chenlin@uic.edu\" TargetMode=\"External\"/><Relationship Id=\"rId7\" T