function init(eli) {
  var STORE = window.STORE_CONFIG || "config";
  var STATE_KEY = "demo_active_phase";
  var OVERLAY_ID = "_eli3_demo_overlay";
  // Collapsed = header bar only (one line, X + chevron). Auto-set after a
  // phase loads so the loaded doc isn't covered; toggle via the chevron.
  var _collapsed = false;
  // Dragged position (left/top) — persists across re-renders (toggle/phase
  // click rebuild the box). Null = default bottom-right anchor. _dragMoved
  // suppresses the header's toggle-click when a drag just happened.
  var _pos = null;
  var _dragMoved = false;

  var PHASES = [
    { n: 1, label: "Phase 1", agreement: "Consulting Agreement" },
    { n: 2, label: "Phase 2", agreement: "OARS DATA" },
    { n: 3, label: "Phase 3", agreement: "Research Agreement" },
  ];

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(msg, type) { if (typeof showToast === "function") showToast(msg, type || "info"); }

  function _getActivePhase() {
    return eli.events.safeAsync(eli.storage.get(STORE, STATE_KEY), "demo.state_read")
      .then(function (row) { return (row && row.phase) || 0; })
      .catch(function () { return 0; });
  }
  function _setActivePhase(n) {
    return eli.events.safeAsync(
      eli.storage.put(STORE, { key: STATE_KEY, phase: n, ts: Date.now() }),
      "demo.state_write"
    ).catch(function () {});
  }

  // Wipe the body and insert the phase document. Placeholder docs insert
  // as styled paragraphs; real docs (kind "ooxml") insert verbatim so
  // formatting + embedded OARS tables arrive exactly as authored.
  // Blank every header/footer slot in every section — leftovers from the
  // trainee's previous doc (or a prior phase) otherwise survive the body
  // replace. Same insertText("", Replace) pattern build_draft uses.
  function _clearAllHF(context) {
    var sections = context.document.sections;
    sections.load("items");
    return context.sync().then(function () {
      var TYPES = ["Primary", "FirstPage", "EvenPages"];
      for (var s = 0; s < sections.items.length; s++) {
        for (var t = 0; t < TYPES.length; t++) {
          try { sections.items[s].getHeader(TYPES[t]).insertText("", "Replace"); } catch (_e) {}
          try { sections.items[s].getFooter(TYPES[t]).insertText("", "Replace"); } catch (_e) {}
        }
      }
      return context.sync();
    });
  }

  function _loadPhaseDoc(doc) {
    return eli.host.runRaw("demo:load_phase", function (context) {
      return _clearAllHF(context).then(function () { return _insertPhaseDoc(context, doc); });
    });
  }
  function _insertPhaseDoc(context, doc) {
    var body = context.document.body;
    if (doc.kind === "ooxml") {
      body.insertOoxml(doc.flatOpc, "Replace");
    } else {
      body.clear();
      if (doc.title) {
        var title = body.insertParagraph(doc.title, "End");
        try { title.styleBuiltIn = "Heading1"; } catch (_e) {}
      }
      // Single insertText — newlines create the paragraphs. One queued op
      // instead of one insertParagraph per paragraph (the per-paragraph
      // version took several seconds on a 5-page doc).
      var txt = (doc.paragraphs || []).map(String).join("\n");
      if (txt) body.insertText(txt, "End");
    }
    if (!doc.normalize) return context.sync();
    // Post-insert direct formatting — host style definitions win on name
    // collision and restyle inserted content (fonts drift, centered
    // titles go left). Direct formatting beats styles. Tracking forced
    // off so this pass never creates revisions attributed to the trainee.
    return context.sync().then(function () {
      try { context.document.changeTrackingMode = "Off"; } catch (_e) {}
      var nb = context.document.body;
      if (doc.normalize.font) nb.font.name = doc.normalize.font;
      if (doc.normalize.size) nb.font.size = doc.normalize.size;
      if (doc.normalize.color) nb.font.color = doc.normalize.color;
      var centerTargets = (doc.normalize.centerBold || []).map(function (t) {
        return String(t).trim().toUpperCase();
      });
      var boldTargets = (doc.normalize.boldExact || []).map(function (t) {
        return String(t).trim().toUpperCase();
      });
      var baseline = doc.normalize.baselineAlign || null;
      // tightSpacing zeros each paragraph's before/after spacing so the
      // deliberate blank paragraphs between blocks are the ONLY gap —
      // otherwise Word's Normal-style "space after" stacks on top of the
      // blank line and the gaps read as oversized on a fresh document.
      var tight = !!doc.normalize.tightSpacing;
      if (!centerTargets.length && !boldTargets.length && !baseline && !tight) return context.sync();
      // centerBold = center + bold the named paragraphs (titles);
      // boldExact = bold only (section headings); baselineAlign = explicit
      // alignment for every OTHER paragraph — without it, body.clear()
      // leaves the host doc's final paragraph formatting alive and every
      // inserted paragraph inherits it (the everything-centered bug).
      var paras = nb.paragraphs;
      paras.load("items/text");
      return context.sync().then(function () {
        for (var i = 0; i < paras.items.length; i++) {
          if (tight) {
            try { paras.items[i].spaceBefore = 0; paras.items[i].spaceAfter = 0; } catch (_sp) {}
          }
          var t = String(paras.items[i].text || "").trim().toUpperCase();
          try {
            if (centerTargets.indexOf(t) !== -1) {
              paras.items[i].alignment = "Centered";
              paras.items[i].font.bold = true;
            } else {
              if (baseline) paras.items[i].alignment = baseline;
              if (boldTargets.indexOf(t) !== -1) paras.items[i].font.bold = true;
            }
          } catch (_e) {}
        }
        return context.sync();
      });
    });
  }

  function _onPhaseClick(phase, rowEl) {
    eli.events.safeAsync(eli.ui.confirm({
      title: "Load " + phase.label + "?",
      message: "This will REPLACE everything in the current Word document with the " +
        phase.label + " agreement (" + phase.agreement + "). Continue?",
    }), "demo.confirm").then(function (ok) {
      if (!ok) return;
      var doc = (typeof window._demoPhaseDoc === "function") ? window._demoPhaseDoc(phase.n) : null;
      if (!doc) { _toast("Phase " + phase.n + " document missing from bundle.", "err"); return; }
      if (rowEl) {
        rowEl.style.pointerEvents = "none";
        var st = rowEl.querySelector("[data-slot='state']");
        if (st) st.textContent = "⏳";
      }
      eli.events.safeAsync(_loadPhaseDoc(doc), "demo.load_phase")
        .then(function () {
          eli.log.event("tool", "demo_phase_loaded", { phase: phase.n, kind: doc.kind });
          _toast("📄 " + phase.label + " loaded — now have the room exit + reload ELI.", "ok");
          // Collapse to the one-line header so the loaded doc isn't covered.
          _collapsed = true;
          return _setActivePhase(phase.n);
        })
        .then(function () { _renderOverlay(); })
        .catch(function (err) {
          eli.log.event("tool", "demo_phase_load_failed", { phase: phase.n, msg: err && err.message });
          _toast("Load failed: " + (err && err.message || "unknown"), "err");
          _renderOverlay();
        });
    });
  }

  function _removeOverlay() {
    var el = document.getElementById(OVERLAY_ID);
    if (el) el.remove();
  }

  // Make `box` draggable by `handle`. Anchors via left/top once moved,
  // clamps to the viewport, and stores the result in _pos so re-renders
  // keep the spot. A real drag sets _dragMoved so the header's toggle
  // click is suppressed.
  function _makeDraggable(box, handle) {
    handle.addEventListener("mousedown", function (ev) {
      if (ev.button !== 0) return;
      if (ev.target.closest("[data-act='close']")) return; // let X work
      var rect = box.getBoundingClientRect();
      var startX = ev.clientX, startY = ev.clientY;
      var origLeft = rect.left, origTop = rect.top;
      _dragMoved = false;
      box.style.left = origLeft + "px"; box.style.top = origTop + "px";
      box.style.right = "auto"; box.style.bottom = "auto";
      function onMove(e) {
        var dx = e.clientX - startX, dy = e.clientY - startY;
        if (!_dragMoved && Math.abs(dx) + Math.abs(dy) < 4) return;
        _dragMoved = true;
        var w = box.offsetWidth, h = box.offsetHeight;
        var nl = Math.max(4, Math.min(window.innerWidth - w - 4, origLeft + dx));
        var nt = Math.max(4, Math.min(window.innerHeight - h - 4, origTop + dy));
        box.style.left = nl + "px"; box.style.top = nt + "px";
        _pos = { left: nl, top: nt };
      }
      function onUp() {
        document.removeEventListener("mousemove", onMove);
        document.removeEventListener("mouseup", onUp);
      }
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
      ev.preventDefault();
    });
  }

  function _renderOverlay() {
    _getActivePhase().then(function (active) {
      _removeOverlay();
      var box = document.createElement("div");
      box.id = OVERLAY_ID;
      box.style.cssText =
        "position:fixed; right:12px; bottom:calc(var(--layout-status-h, 26px) + 10px); width:228px; z-index:99990;" +
        "background:linear-gradient(160deg,#0d1b2a 0%,#1b263b 100%); border:1px solid #c9a227; border-radius:10px;" +
        "box-shadow:0 10px 32px rgba(13,27,42,0.5); font:500 11px/1.4 'Inter','Segoe UI',sans-serif; color:#e2e8f0; overflow:hidden;";
      // Restore the dragged position, switching off the bottom-right anchor.
      if (_pos) {
        box.style.left = _pos.left + "px"; box.style.top = _pos.top + "px";
        box.style.right = "auto"; box.style.bottom = "auto";
      }
      var rows = PHASES.map(function (p) {
        var isActive = active === p.n;
        var isReal = false;
        try {
          var _d = window._demoPhaseDoc && window._demoPhaseDoc(p.n);
          isReal = !!(_d && (_d.kind === "ooxml" || _d.final === true));
        } catch (_e) {}
        return '<div data-phase="' + p.n + '" title="Load the ' + _esc(p.agreement) + '" style="display:flex; align-items:center; gap:8px; padding:8px 10px; cursor:pointer; border-top:1px solid rgba(255,255,255,0.07);' + (isActive ? "background:rgba(201,162,39,0.14);" : "") + '">' +
          '<span style="flex:0 0 auto; width:22px; height:22px; border-radius:6px; background:rgba(201,162,39,0.18); border:1px solid #c9a227; color:#f2d866; display:flex; align-items:center; justify-content:center; font:800 11px/1 Georgia,serif;">' + p.n + '</span>' +
          '<span style="flex:1; min-width:0;">' +
            '<span style="display:block; font:700 10.5px/1.2 Inter,sans-serif; color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">' + _esc(p.agreement) + '</span>' +
            (isReal ? '' : '<span style="font:700 7.5px/1 Inter,sans-serif; color:#fbbf24; letter-spacing:0.08em;">PLACEHOLDER</span>') +
          '</span>' +
          '<span data-slot="state" style="flex:0 0 auto; font-size:12px;">' + (isActive ? "✅" : "▶") + '</span>' +
        '</div>';
      }).join("");
      var headerBorder = _collapsed ? "" : "border-bottom:2px solid #c9a227;";
      // Phase 1: a mascot-led tour of the dashboard (dispatches to
      // dashboard_tour). Sits above the doc-loading phases; non-destructive.
      var tourBtn =
        '<div data-act="tour" title="Run the guided dashboard tour" style="display:flex; align-items:center; gap:8px; margin:8px 10px; padding:8px 10px; cursor:pointer; border-radius:8px; border:1px solid rgba(201,162,39,0.55); background:linear-gradient(135deg, rgba(242,216,102,0.16), rgba(201,162,39,0.10));">' +
          '<span style="flex:0 0 auto; font-size:14px;">🧭</span>' +
          '<span style="flex:1; min-width:0; font:800 10.5px/1.2 Inter,sans-serif; letter-spacing:0.04em; color:#f2d866;">DASHBOARD TOUR</span>' +
          '<span style="flex:0 0 auto; font-size:12px; color:#c9a227;">▶</span>' +
        '</div>';
      box.innerHTML =
        '<div data-act="header" style="display:flex; align-items:center; gap:8px; padding:8px 10px; cursor:move;' + headerBorder + '">' +
          '<span style="font-size:13px;">🎬</span>' +
          '<span style="font:800 11px/1 Georgia,serif; color:#fff; letter-spacing:0.04em;">DEMO DIRECTOR</span>' +
          '<span style="flex:1"></span>' +
          '<button data-act="toggle" title="' + (_collapsed ? "Expand" : "Minimize") + '" style="border:none; background:transparent; color:#c9a227; font:700 11px/1 Inter,sans-serif; cursor:pointer; padding:0 4px;">' + (_collapsed ? "▸" : "▾") + '</button>' +
          '<button data-act="close" title="Close" style="border:none; background:transparent; color:#94a3b8; font-size:13px; cursor:pointer; padding:0 2px;">✕</button>' +
        '</div>' +
        (_collapsed ? '' : tourBtn + rows);
      document.body.appendChild(box);
      // If a restored position now overflows (e.g. expanded taller than the
      // viewport allows), clamp it back inside.
      if (_pos) {
        var maxTop = window.innerHeight - box.offsetHeight - 4;
        var ct = Math.max(4, Math.min(_pos.top, Math.max(4, maxTop)));
        var maxLeft = window.innerWidth - box.offsetWidth - 4;
        var cl = Math.max(4, Math.min(_pos.left, Math.max(4, maxLeft)));
        box.style.top = ct + "px"; box.style.left = cl + "px";
        _pos.top = ct; _pos.left = cl;
      }
      var headerEl = box.querySelector("[data-act='header']");
      _makeDraggable(box, headerEl);
      // X closes; clicking anywhere else in the header toggles min/maximize
      // — but not when the click is the tail end of a drag.
      box.querySelector("[data-act='close']").onclick = function (ev) {
        ev.stopPropagation();
        _removeOverlay();
      };
      headerEl.onclick = function () {
        if (_dragMoved) { _dragMoved = false; return; }
        _collapsed = !_collapsed;
        _renderOverlay();
      };
      if (!_collapsed) {
        var tourEl = box.querySelector("[data-act='tour']");
        if (tourEl) tourEl.onclick = function () {
          // Hide the director so it doesn't sit over the tour, then launch
          // the reusable dashboard_tour tool.
          _removeOverlay();
          try { if (eli.dispatch) eli.dispatch("tour", "start"); } catch (_e) {}
        };
        PHASES.forEach(function (p) {
          var row = box.querySelector('[data-phase="' + p.n + '"]');
          if (row) row.onclick = function () { _onPhaseClick(p, row); };
        });
      }
    });
  }

  // Locked until Wed Jun 17, 2026 (local midnight). The tile is visible on
  // everyone's dashboard now; clicking before then shows a coming-soon
  // notice. It self-unlocks on each user's own clock — no redeploy needed.
  // Admins can unlock early on their OWN machine via the admin password
  // (eli_admin_password is only present on admin machines). The bypass is
  // per-machine (localStorage) so it never leaks to colleagues.
  var _UNLOCK_TS = new Date(2026, 5, 17, 0, 0, 0).getTime();
  var EARLY_KEY = "eli_demo_early_unlock";
  function _earlyUnlocked() {
    try { return (eli.compat && eli.compat.lsGet(EARLY_KEY)) === "1"; } catch (_) { return false; }
  }
  function _isLocked() { return Date.now() < _UNLOCK_TS && !_earlyUnlocked(); }

  function _adminUnlock() {
    var stored = null;
    try { stored = eli.compat && eli.compat.lsGet("eli_admin_password"); } catch (_) {}
    if (!stored) {
      try { eli.ui.alert({ title: "Admin password not set", messageText: "No admin password is configured on this machine, so the Demo can't be unlocked early here." }); } catch (_) {}
      return;
    }
    eli.events.safeAsync(eli.ui.prompt({
      title: "🔓 Admin early-unlock",
      icon: "🔒",
      inputType: "password",
      messageText: "Enter the admin password to unlock the Demo before Wednesday (this machine only).",
      confirmLabel: "Unlock",
    }), "demo.admin_unlock").then(function (pw) {
      if (pw == null || pw === "") return;
      if (pw === stored) {
        try { eli.compat.lsSet(EARLY_KEY, "1"); } catch (_) {}
        _toast("🔓 Demo unlocked on this machine.", "ok");
        _renderOverlay();
      } else {
        _toast("Incorrect admin password.", "err");
      }
    }).catch(function () {});
  }

  function _showLockedNotice() {
    eli.events.safeAsync(eli.ui.confirm({
      icon: "🔒",
      title: "Demo unlocks Wednesday",
      messageText: "The training Demo opens Wednesday, June 17 — it'll be ready to run then.\n\nAdmins can unlock it early on this machine.",
      confirmLabel: "Admin Unlock",
      cancelLabel: "Close",
    }), "demo.locked_notice").then(function (wantsUnlock) {
      if (wantsUnlock) _adminUnlock();
    }).catch(function () {});
  }

  eli.register({
    tile: { app_demo: function () {
      if (_isLocked()) { _showLockedNotice(); return; }
      try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedDemo"); } catch (_) {}
      // Toggle: clicking the tile again closes the overlay.
      if (document.getElementById(OVERLAY_ID)) { _removeOverlay(); return; }
      _renderOverlay();
    } },
  });
}
